
'use client';

import { useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase/client';
import type { Claim } from '@/lib/types';
import { Skeleton } from '@/components/ui/skeleton';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Terminal, Frown, Trash2, Loader2, Contact } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { format } from 'date-fns';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { useToast } from '@/hooks/use-toast';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';

type EnrichedClaim = Claim & {
  item: { 
    id: string;
    name: string;
    reporter: {
      full_name: string | null;
      email: string | null;
    } | null;
  } | null;
};

export default function MyClaimsPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [claims, setClaims] = useState<EnrichedClaim[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);

  useEffect(() => {
    const fetchUserClaims = async () => {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        router.push('/login');
        return;
      }

      const { data, error } = await supabase
        .from('claims')
        .select(`
          *,
          item:items(
            id, 
            name,
            reporter:profiles(full_name, email)
          )
        `)
        .eq('claimant_id', user.id)
        .order('created_at', { ascending: false });

      if (error) {
        setError(error.message);
        console.error('Error fetching user claims:', error.message);
      } else {
        setClaims(data as EnrichedClaim[]);
      }
      setLoading(false);
    };

    fetchUserClaims();
  }, [router]);
  
  const handleDeleteClaim = async (claimToDelete: EnrichedClaim) => {
    setIsDeleting(claimToDelete.id);
    try {
        if (claimToDelete.proof_image_urls && claimToDelete.proof_image_urls.length > 0) {
            const filePaths = claimToDelete.proof_image_urls.map(url => url.substring(url.indexOf('claims/')));
            const { error: storageError } = await supabase.storage.from('item_images').remove(filePaths);
            if (storageError) {
                console.error("Error deleting proof images:", storageError.message);
            }
        }

        const { error: dbError } = await supabase.from('claims').delete().eq('id', claimToDelete.id);

        if (dbError) throw dbError;

        setClaims(prev => prev.filter(c => c.id !== claimToDelete.id));
        toast({
            title: 'Claim Deleted',
            description: 'Your claim has been successfully withdrawn and deleted.',
        });

    } catch (error: any) {
        toast({
            title: 'Error Deleting Claim',
            description: error.message,
            variant: 'destructive',
        });
    } finally {
        setIsDeleting(null);
    }
  };

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
        case 'pending': return 'default';
        case 'approved': return 'secondary';
        case 'rejected': return 'destructive';
        default: return 'outline';
    }
  }

  return (
    <div className="container mx-auto max-w-4xl px-4 py-8">
      <div className="space-y-4 mb-8">
        <h1 className="text-3xl font-bold tracking-tight">My Submitted Claims</h1>
        <p className="text-muted-foreground">
          Track the status of all the claims you have submitted for found items.
        </p>
      </div>

      {loading ? (
        <div className="space-y-4">
          <Skeleton className="h-24 w-full" />
          <Skeleton className="h-24 w-full" />
          <Skeleton className="h-24 w-full" />
        </div>
      ) : error ? (
        <Alert variant="destructive">
            <Terminal className="h-4 w-4" />
            <AlertTitle>Error</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : claims.length > 0 ? (
        <Card>
            <CardContent className="p-0">
                <Accordion type="multiple" className="w-full">
                    {claims.map(claim => (
                        <AccordionItem value={claim.id} key={claim.id} className="border-b px-4">
                            <div className="flex w-full items-center justify-between group">
                                <AccordionTrigger className="flex-1 py-4 text-left hover:no-underline [&>svg]:ml-4">
                                  <div>
                                    <Link href={`/items/${claim.item?.id}`} className="font-semibold text-primary hover:underline" onClick={(e) => e.stopPropagation()}>
                                        Claim on "{claim.item?.name || 'an item'}"
                                    </Link>
                                    <p className="text-sm text-muted-foreground mt-1">
                                        Submitted on {format(new Date(claim.created_at), "PPP")}
                                    </p>
                                  </div>
                                </AccordionTrigger>
                                <div className="flex items-center gap-2 pl-2" onClick={(e) => e.stopPropagation()}>
                                    <Badge variant={getStatusBadgeVariant(claim.status)} className="capitalize">{claim.status}</Badge>
                                    <AlertDialog>
                                        <AlertDialogTrigger asChild>
                                            <Button variant="ghost" size="icon" className="text-destructive hover:text-destructive h-8 w-8" disabled={isDeleting === claim.id}>
                                                {isDeleting === claim.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                                            </Button>
                                        </AlertDialogTrigger>
                                        <AlertDialogContent>
                                            <AlertDialogHeader>
                                                <AlertDialogTitle>Are you sure?</AlertDialogTitle>
                                                <AlertDialogDescription>
                                                    This action cannot be undone. This will permanently withdraw and delete your claim for "{claim.item?.name}".
                                                </AlertDialogDescription>
                                            </AlertDialogHeader>
                                            <AlertDialogFooter>
                                                <AlertDialogCancel>Cancel</AlertDialogCancel>
                                                <AlertDialogAction onClick={() => handleDeleteClaim(claim)} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                                                    Delete Claim
                                                </AlertDialogAction>
                                            </AlertDialogFooter>
                                        </AlertDialogContent>
                                    </AlertDialog>
                                </div>
                            </div>
                            <AccordionContent className="space-y-4 pb-4">
                                <h4 className="font-semibold text-sm">Identifying Marks Provided:</h4>
                                <ul className="list-disc pl-5 space-y-1 text-sm text-muted-foreground">
                                    {claim.identification_marks.map((mark, index) => (
                                        <li key={index}>{mark}</li>
                                    ))}
                                </ul>
                                
                                {claim.status === 'approved' && (
                                  <div className="rounded-md border border-green-200 bg-green-50 p-4">
                                      <div className="flex items-start gap-3">
                                        <Contact className="h-5 w-5 text-green-700 mt-0.5" />
                                        <div>
                                          <h4 className="font-semibold text-sm text-green-900">Contact the Finder</h4>
                                          <p className="text-sm text-green-800 mt-1">Your claim was approved! Please contact the person who found your item to arrange its return.</p>
                                          <div className="mt-3 text-sm space-y-1">
                                            <p><strong className="font-medium text-green-900">Name:</strong> {claim.item?.reporter?.full_name || 'Not available'}</p>
                                            <p><strong className="font-medium text-green-900">Email:</strong> {claim.item?.reporter?.email || 'Not available'}</p>
                                          </div>
                                        </div>
                                      </div>
                                  </div>
                                )}

                                {claim.status === 'rejected' && (
                                   <div className="rounded-md border border-red-200 bg-red-50 p-4 text-sm text-red-800">
                                      <p><strong className="font-medium">Reason for Rejection:</strong> The finder, {claim.item?.reporter?.full_name || 'the reporter'}, could not verify ownership based on the details provided. Ensure your identifying marks are not visible in public photos.</p>
                                   </div>
                                )}
                            </AccordionContent>
                        </AccordionItem>
                    ))}
                </Accordion>
            </CardContent>
        </Card>
      ) : (
        <Card className="flex flex-col items-center justify-center py-16 text-center">
            <CardHeader>
                <div className="mx-auto bg-muted rounded-full p-3 w-fit mb-4">
                    <Frown className="h-8 w-8 text-muted-foreground" />
                </div>
                <CardTitle>No Claims Submitted</CardTitle>
                <CardDescription>You haven't submitted any claims yet.</CardDescription>
            </CardHeader>
            <CardContent>
                <Button asChild>
                    <Link href="/">Browse Found Items</Link>
                </Button>
            </CardContent>
        </Card>
      )}
    </div>
  );
}
